export fn palindrome_singly_linked_list(v:[*c]const i64,n:usize)i64{if(v==null or n<1 or n>65 or v[0]<0 or v[0]>64 or n!=@as(usize,@intCast(v[0]))+1)return -1;const len:usize=@intCast(v[0]);for(1..n)|i|if(v[i]<-2147483648 or v[i]>2147483647)return -1;var slow:usize=0;var fast:usize=0;while(fast+1<len){slow+=1;fast+=2;}const suffix=len-slow;for(0..suffix)|i|if(v[i+1]!=v[len-i])return 0;return 1;}
